 for a in alphabet {corpus.push(vec![a]);for b in alphabet {corpus.push(vec![a,b]);}}
 for a in 0..=255 {corpus.push(vec![a]);corpus.push(vec![b'/',a]);corpus.push(vec![a,b'/']);}
